// Authentication tables (users, sessions, accounts, verifications, jwks, workspaces,
// workspace_members, workspace_invitations) are generated by Better Auth from the
// configuration in services/backend/src/auth/auth.ts. Do not edit auth-schema.ts by
// hand: change the configuration and run `pnpm auth:generate`.
// Application tables are added here as later phases need them.
import { sql } from "drizzle-orm";
import {
  customType,
  foreignKey,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  timestamp,
  unique,
  uuid,
} from "drizzle-orm/pg-core";
import { users, workspaces } from "./auth-schema";

export * from "./auth-schema";

/** Postgres bytea as a Uint8Array (drizzle has no built-in column for it). */
const bytea = customType<{ data: Uint8Array; driverData: Uint8Array }>({
  dataType: () => "bytea",
});

export const projects = pgTable(
  "projects",
  {
    id: uuid("id")
      .default(sql`pg_catalog.gen_random_uuid()`)
      .primaryKey(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    createdBy: uuid("created_by").references(() => users.id, {
      onDelete: "set null",
    }),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [
    // Target of canvases' composite foreign key.
    unique("projects_id_workspace_id_unique").on(table.id, table.workspaceId),
    index("projects_workspace_id_idx").on(table.workspaceId),
  ],
);

/**
 * One row per canvas: the authoritative Yjs state, the JSON snapshot derived from it by
 * the server, and an integer `version` for optimistic locking. `workspace_id` repeats the
 * project's workspace so authorization needs only a join with workspace_members; the
 * composite foreign key makes the database keep the two in agreement.
 */
export const canvases = pgTable(
  "canvases",
  {
    id: uuid("id")
      .default(sql`pg_catalog.gen_random_uuid()`)
      .primaryKey(),
    projectId: uuid("project_id").notNull(),
    workspaceId: uuid("workspace_id").notNull(),
    name: text("name").notNull(),
    yjsState: bytea("yjs_state").notNull(),
    snapshot: jsonb("snapshot").notNull(),
    schemaVersion: integer("schema_version").notNull(),
    version: integer("version").default(0).notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
    updatedBy: uuid("updated_by").references(() => users.id, {
      onDelete: "set null",
    }),
  },
  (table) => [
    foreignKey({
      columns: [table.projectId, table.workspaceId],
      foreignColumns: [projects.id, projects.workspaceId],
      name: "canvases_project_workspace_fk",
    }).onDelete("cascade"),
    index("canvases_project_id_idx").on(table.projectId),
    index("canvases_workspace_id_idx").on(table.workspaceId),
  ],
);

export const runs = pgTable(
  "runs",
  {
    id: uuid("id")
      .default(sql`pg_catalog.gen_random_uuid()`)
      .primaryKey(),
    canvasId: uuid("canvas_id")
      .notNull()
      .references(() => canvases.id, { onDelete: "cascade" }),
    projectId: uuid("project_id")
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    createdBy: uuid("created_by").references(() => users.id, {
      onDelete: "set null",
    }),
    status: text("status").default("queued").notNull(),
    canvasVersion: integer("canvas_version").notNull(),
    snapshot: jsonb("snapshot").notNull(),
    options: jsonb("options")
      .$type<Record<string, unknown>>()
      .default({})
      .notNull(),
    workflowId: text("workflow_id").notNull(),
    error: text("error"),
    createdAt: timestamp("created_at", { withTimezone: true })
      .defaultNow()
      .notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
    startedAt: timestamp("started_at", { withTimezone: true }),
    completedAt: timestamp("completed_at", { withTimezone: true }),
  },
  (table) => [
    index("runs_canvas_id_idx").on(table.canvasId),
    index("runs_project_id_idx").on(table.projectId),
    index("runs_workspace_id_idx").on(table.workspaceId),
    index("runs_created_by_idx").on(table.createdBy),
  ],
);

export const node_runs = pgTable(
  "node_runs",
  {
    id: uuid("id")
      .default(sql`pg_catalog.gen_random_uuid()`)
      .primaryKey(),
    runId: uuid("run_id")
      .notNull()
      .references(() => runs.id, { onDelete: "cascade" }),
    nodeId: text("node_id").notNull(),
    nodeType: text("node_type").notNull(),
    provider: text("provider"),
    externalJobId: text("external_job_id"),
    status: text("status").default("pending").notNull(),
    inputs: jsonb("inputs"),
    outputs: jsonb("outputs"),
    error: text("error"),
    createdAt: timestamp("created_at", { withTimezone: true })
      .defaultNow()
      .notNull(),
    startedAt: timestamp("started_at", { withTimezone: true }),
    completedAt: timestamp("completed_at", { withTimezone: true }),
  },
  (table) => [
    unique("node_runs_run_id_node_id_unique").on(table.runId, table.nodeId),
    unique("node_runs_provider_external_job_id_unique").on(
      table.provider,
      table.externalJobId,
    ),
    index("node_runs_run_id_idx").on(table.runId),
  ],
);

export const assets = pgTable(
  "assets",
  {
    id: uuid("id")
      .default(sql`pg_catalog.gen_random_uuid()`)
      .primaryKey(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    key: text("key").notNull().unique(),
    contentType: text("content_type").notNull(),
    sizeBytes: integer("size_bytes").notNull(),
    status: text("status").default("pending").notNull(),
    metadata: jsonb("metadata").$type<Record<string, unknown>>(),
    createdBy: uuid("created_by").references(() => users.id, {
      onDelete: "set null",
    }),
    createdAt: timestamp("created_at", { withTimezone: true })
      .defaultNow()
      .notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index("assets_workspace_id_idx").on(table.workspaceId)],
);

export const agent_runs = pgTable(
  "agent_runs",
  {
    id: uuid("id")
      .default(sql`pg_catalog.gen_random_uuid()`)
      .primaryKey(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    projectId: uuid("project_id")
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    canvasId: uuid("canvas_id")
      .notNull()
      .references(() => canvases.id, { onDelete: "cascade" }),
    createdBy: uuid("created_by").references(() => users.id, {
      onDelete: "set null",
    }),
    profileId: text("profile_id").notNull(),
    prompt: text("prompt").notNull(),
    routeHints: jsonb("route_hints"),
    canvasVersion: integer("canvas_version").notNull(),
    canvasSnapshot: jsonb("canvas_snapshot").notNull(),
    status: text("status").default("running").notNull(),
    outcome: text("outcome"),
    state: jsonb("state").default({ steps: [], proposals: [] }).notNull(),
    stateVersion: integer("state_version").default(0).notNull(),
    workflowId: text("workflow_id").notNull(),
    error: text("error"),
    createdAt: timestamp("created_at", { withTimezone: true })
      .defaultNow()
      .notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
    completedAt: timestamp("completed_at", { withTimezone: true }),
  },
  (table) => [
    index("agent_runs_workspace_id_idx").on(table.workspaceId),
    index("agent_runs_project_id_idx").on(table.projectId),
    index("agent_runs_canvas_id_idx").on(table.canvasId),
    index("agent_runs_created_by_idx").on(table.createdBy),
    index("agent_runs_status_idx").on(table.status),
  ],
);
